const itens = $input.all().map(i => i.json);

const DIA = 24 * 60 * 60 * 1000;
const paraMs = (iso) => Date.parse(iso + 'T00:00:00Z');
const agora = new Date();
const hoje = Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth(), agora.getUTCDate());
const dias = (de, ate) => Math.round((ate - de) / DIA);

const media = (nums) =>
  nums.length ? Math.round((nums.reduce((a, b) => a + b, 0) / nums.length) * 10) / 10 : null;

const contar = (lista, campo) =>
  lista.reduce((acc, d) => {
    acc[d[campo]] = (acc[d[campo]] || 0) + 1;
    return acc;
  }, {});

const resolvidas = itens.filter(d => d.status === 'Resolvida' && d.data_resolucao);
const emAberto = itens.filter(d => d.status !== 'Resolvida');

const tempoResolucao = (d) => dias(paraMs(d.data_abertura), paraMs(d.data_resolucao));

const porSistema = [...new Set(itens.map(d => d.sistema))]
  .map(nome => {
    const doSistema = itens.filter(d => d.sistema === nome);
    const abertas = doSistema.filter(d => d.status !== 'Resolvida');
    const resolvidasDoSistema = doSistema.filter(d => d.status === 'Resolvida' && d.data_resolucao);
    return {
      sistema: nome,
      total: doSistema.length,
      em_aberto: abertas.length,
      alta_em_aberto: abertas.filter(d => d.prioridade === 'Alta').length,
      tempo_medio_resolucao_dias: media(resolvidasDoSistema.map(tempoResolucao)),
    };
  })
  .sort((a, b) => b.total - a.total);

const criticas = emAberto
  .filter(d => d.prioridade === 'Alta')
  .map(d => ({
    numero: d.numero,
    sistema: d.sistema,
    descricao: d.descricao,
    status: d.status,
    dias_em_aberto: dias(paraMs(d.data_abertura), hoje),
  }))
  .filter(d => d.dias_em_aberto > 7)
  .sort((a, b) => b.dias_em_aberto - a.dias_em_aberto);

return [{
  json: {
    data_relatorio: new Date(hoje).toISOString().slice(0, 10),
    total_demandas: itens.length,
        alta_prioridade_em_aberto: emAberto.filter(d => d.prioridade === 'Alta').length,
    por_status: contar(itens, 'status'),
    por_prioridade: contar(itens, 'prioridade'),
    tempo_medio_resolucao_dias: media(resolvidas.map(tempoResolucao)),
    por_sistema: porSistema,
    alta_prioridade_parada_mais_de_7_dias: criticas,
  },
}];
